            let (enabled, severity) = parse_severity_string(&severity_str)?;
            if enabled {
                categories.insert(category, severity);
            } else {
                // "off" means the category is disabled — store None.
                categories.insert(category, None);
            }
        }

        Ok(Self {
            exclude: file.lint.exclude,
            rules,
            categories,
